 private com.fulllock.app.PickupCoordinates.Point pickupPoint(View root,String key){if(controls==null||!controls.getBoolean("cardShowPickup")||!controls.getBoolean("drawCards",true)||!root.isShown()||!semanticDigest(root).equals(key))return null;View boundRoot=root;ExactBinding binding=null;for(int i=0;i<10&&boundRoot!=null;i++){ExactBinding candidate=exactBindings.get(boundRoot);if(candidate!=null&&boundRoot.findViewById(originId)==root.findViewById(originId)&&candidate.key().equals(semanticDigest(boundRoot))){binding=candidate;break;}if(boundRoot.getClass().getName().contains("RecyclerView"))break;boundRoot=boundRoot.getParent() instanceof View?(View)boundRoot.getParent():null;}if(binding==null){pickupDebug="no-current-binding";return null;}View first=root.findViewById(originId),last=root.findViewById(destId),price=root.findViewById(priceId);if(!(first instanceof TextView a)||!(last instanceof TextView b)||!(price instanceof TextView fare))return null;java.util.List<Object> models=new java.util.ArrayList<>();for(BoundModel ref:binding.models()){Object model=ref.object().get();if(model!=null&&ref.uuid().equals(String.valueOf(getter(model,"getUuid"))))models.add(model);}var point=com.fulllock.app.PickupCoordinates.resolve(models,a.getText().toString(),b.getText().toString(),fare.getText().toString(),true);pickupDebug="models="+models.size()+" valid="+(point!=null);if(point==null&&!models.isEmpty()){Object m=models.get(0),stops=getter(m,"getAddrInfo");Object mask=getter(m,"getMaskedAddress");pickupDebug+=" mask="+String.valueOf(mask);if(stops instanceof java.util.List<?> list&&!list.isEmpty()){Object loc=getter(list.get(0),"getLatLng");pickupDebug+=" coordinateType="+(loc==null?"null":loc.getClass().getName());}}return point;}
 private void applyPickupTags(){java.util.List<PickupTags.Target> targets=new java.util.ArrayList<>();if(controls!=null&&controls.getBoolean("cardShowPickup")&&controls.getBoolean("drawCards",true))for(var ref:new java.util.ArrayList<>(cards.values())){View root=ref.get();if(root==null)continue;View origin=root.findViewById(originId);if(origin instanceof TextView text){String key=semanticDigest(root);targets.add(new PickupTags.Target(root,text,()->pickupPoint(root,key)));}}pickupTags.update(targets);}
 private void prepareDetail(View click){java.util.List<Object> models=new java.util.ArrayList<>();for(var reference:new java.util.ArrayList<>(cards.values())){View card=reference.get();if(card==null||!card.isShown()||findClickTarget(card)!=click)continue;View parent=card;for(int i=0;i<10&&parent!=null;i++){ExactBinding binding=exactBindings.get(parent);if(binding!=null&&binding.key().equals(semanticDigest(parent))&&parent.findViewById(originId)==card.findViewById(originId)){for(BoundModel ref:binding.models()){Object model=ref.object().get();if(model!=null&&ref.uuid().equals(String.valueOf(getter(model,"getUuid"))))models.add(model);}break;}parent=parent.getParent() instanceof View?(View)parent.getParent():null;}}if(!models.isEmpty())detail.prepare(models);}
 private void appendJobIdentities(JSONArray rows)throws Exception{for(var entry:new java.util.ArrayList<>(exactBindings.entrySet())){View root=entry.getKey();ExactBinding binding=entry.getValue();if(!root.isShown()||!binding.key().equals(contentKey(root)))continue;String uuid=null;boolean conflict=false;for(BoundModel ref:binding.models()){Object model=ref.object().get();if(model==null||!ref.uuid().equals(String.valueOf(getter(model,"getUuid"))))continue;if(uuid!=null&&!uuid.equals(ref.uuid())){conflict=true;break;}uuid=ref.uuid();}if(uuid==null||conflict)continue;View origin=root.findViewById(originId);Rect r=new Rect();if(origin==null||!origin.getGlobalVisibleRect(r)||rows.length()>=60)continue;byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(uuid.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder id=new StringBuilder();for(int i=0;i<12;i++)id.append(String.format(java.util.Locale.ROOT,"%02x",digest[i]&255));rows.put(node(origin,r,"jobIdentity",id.toString()));}}
 private void appendDistances(JSONArray rows)throws Exception{for(View root:new java.util.ArrayList<>(boundModels.keySet())){if(!root.isShown())continue;refreshDistance(root);BoundDistance data=routeDistances.get(root);if(data==null)continue;View origin=root.findViewById(originId);Rect r=new Rect();if(origin!=null&&origin.getGlobalVisibleRect(r)&&rows.length()<60)rows.put(node(origin,r,"routeDistance",Double.toString(data.metres())));}}
