 private final java.util.WeakHashMap<View,android.graphics.RectF> headerCache=new java.util.WeakHashMap<>();
 private android.graphics.RectF header(View root){android.graphics.RectF value=headerCache.get(root);if(value==null){value=computeHeader(root);headerCache.put(root,value);}return value;}
 private android.graphics.RectF computeHeader(View root){java.util.ArrayList<View> queue=new java.util.ArrayList<>();queue.add(root);float d=c.getResources().getDisplayMetrics().density;for(int i=0;i<queue.size()&&i<500;i++){View view=queue.get(i);if(view instanceof TextView){String t=String.valueOf(((TextView)view).getText());android.graphics.RectF r=relative(root,view);if(r.top<64*d&&(t.contains("ขนส่งทันที")||t.matches(".*[0-9]{1,2}:[0-9]{2}.*"))){View parent=view;for(int n=0;n<5&&parent!=root;n++){android.graphics.RectF pr=relative(root,parent);if(pr.width()>root.getWidth()*.7f&&pr.height()>=26*d&&pr.height()<=64*d)return pr;parent=parent.getParent() instanceof View?(View)parent.getParent():root;}return new android.graphics.RectF(0,Math.max(0,r.centerY()-18*d),root.getWidth(),r.centerY()+18*d);}}if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int n=0;n<g.getChildCount();n++)queue.add(g.getChildAt(n));}}return new android.graphics.RectF(0,0,root.getWidth(),36*d);}
 private float summaryRow(View root,float d){java.util.ArrayList<View> queue=new java.util.ArrayList<>();queue.add(root);for(int i=0;i<queue.size()&&i<500;i++){View v=queue.get(i);if(v instanceof TextView){String text=String.valueOf(((TextView)v).getText()).trim();if(text.matches("(?i)^(มอเตอร์ไซค์|motorbike|motorcycle|รถกระบะ.*|รถเก๋ง.*|รถตู้.*|รถบรรทุก.*)$"))return relative(root,v).centerY()-18*d;}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)queue.add(g.getChildAt(n));}}View destination=root.findViewById(destId);return destination==null?Float.NaN:relative(root,destination).bottom+12*d;}
 private android.graphics.RectF freeInRow(java.util.List<android.graphics.RectF> used,float y,float w,float h,float width,float d){if(!Float.isFinite(y))return null;for(float x=12*d;x+w<=width-10*d;x+=6*d){android.graphics.RectF r=new android.graphics.RectF(x,y,x+w,y+h),check=new android.graphics.RectF(r);check.inset(-3*d,-2*d);boolean hit=false;for(android.graphics.RectF old:used)if(android.graphics.RectF.intersects(old,check)){hit=true;break;}if(!hit){used.add(r);return r;}}return null;}
 private android.graphics.RectF freeAcross(java.util.List<android.graphics.RectF> used,float y,float w,float h,float width,float d){for(float yy=y;yy>=48*d;yy-=6*d)for(float x=12*d;x+w<=width-10*d;x+=6*d){android.graphics.RectF r=new android.graphics.RectF(x,yy,x+w,yy+h),check=new android.graphics.RectF(r);check.inset(-3*d,-2*d);boolean hit=false;for(android.graphics.RectF old:used)if(android.graphics.RectF.intersects(old,check)){hit=true;break;}if(!hit){used.add(r);return r;}}return null;}
 private android.graphics.RectF free(java.util.List<android.graphics.RectF> used,float x,float y,float w,float h,float floor,float d,boolean downward){for(float yy=y;downward?yy+h<=floor:yy>=48*d;yy+=(downward?6:-6)*d){android.graphics.RectF r=new android.graphics.RectF(x,yy,x+w,yy+h),check=new android.graphics.RectF(r);check.inset(-3*d,-2*d);boolean hit=false;for(android.graphics.RectF old:used)if(android.graphics.RectF.intersects(old,check)){hit=true;break;}if(!hit){used.add(r);return r;}}return null;}
 private void applyInfo(java.util.List<ScreenCardParser.Card> parsedCards)throws Exception{
  java.util.Set<View> retained=java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<>());if(controls==null||!controls.getBoolean("drawCards",true)){clearInfo();return;}float d=c.getResources().getDisplayMetrics().density;JSONObject pricingRules=new JSONObject(controls.getString("rules","{}"));int fee=pricingRules.optInt("fee",20);
  for(ScreenCardParser.Card parsed:parsedCards){String token=parsed.token();View card=cards.containsKey(token)?cards.get(token).get():null;if(card==null||!(card instanceof ViewGroup)||card.getWidth()<220*d)continue;retained.add(card);
   String layoutKey=controls.getString("overlayStyleKey","")+token+":"+fee+":"+parsed.routeKm()+":"+parsed.pickupKm()+":"+parsed.commissionReduction()+":"+controls.getString("rules","")+":"+card.getWidth()+":"+card.getHeight()+":"+summaryRow(card,d)+":"+controls.getBoolean("cardShowNet",true)+controls.getBoolean("cardShowDistance",true)+controls.getBoolean("cardShowRate",true);if(layoutKey.equals(infoLayoutKeys.get(card))&&info.containsKey(card))continue;
   java.util.List<android.graphics.RectF> occupied=new java.util.ArrayList<>();occupied(card,card,occupied,new int[]{0});View price=card.findViewById(priceId);if(price==null)continue;int[] base=new int[2],priceAt=new int[2];card.getLocationOnScreen(base);price.getLocationOnScreen(priceAt);float floor=priceAt[1]-base[1]-6*d;
   java.util.List<CardInfoDrawable.Slot> slots=new java.util.ArrayList<>();String net="฿"+com.fulllock.app.Commission.net(parsed.job(),fee,parsed.commissionReduction()).toPlainString(),km=parsed.routeKm()==null?"—":java.math.BigDecimal.valueOf(parsed.routeKm()).setScale(2,java.math.RoundingMode.HALF_UP).stripTrailingZeros().toPlainString()+" กม.",rate=OverlayRate.text(pricingRules,parsed);
   boolean distanceOn=controls.getBoolean("cardShowDistance",true),rateOn=controls.getBoolean("cardShowRate",true);boolean pair=false;float rowY=summaryRow(card,d);
   if(distanceOn&&rateOn){android.graphics.RectF r=freeInRow(occupied,rowY,156*d,30*d,card.getWidth(),d);if(r==null)r=freeInRow(occupied,rowY+4*d,140*d,30*d,card.getWidth(),d);if(r!=null){float half=(r.width()-4*d)/2;slots.add(new CardInfoDrawable.Slot(new android.graphics.RectF(r.left,r.top,r.left+half,r.bottom),"ระยะทางงาน",km,false));slots.add(new CardInfoDrawable.Slot(new android.graphics.RectF(r.left+(r.width()+4*d)/2,r.top,r.right,r.bottom),"ราคา / กม.",rate,false));pair=true;}}
   if(distanceOn&&rateOn&&!pair){android.graphics.RectF distanceSlot=freeInRow(occupied,rowY,72*d,30*d,card.getWidth(),d);if(distanceSlot==null)distanceSlot=freeAcross(occupied,floor-32*d,72*d,30*d,card.getWidth(),d);if(distanceSlot!=null)slots.add(new CardInfoDrawable.Slot(distanceSlot,"ระยะทางงาน",km,false));android.graphics.RectF rateSlot=freeInRow(occupied,rowY,72*d,30*d,card.getWidth(),d);if(rateSlot==null)rateSlot=freeAcross(occupied,floor-32*d,72*d,30*d,card.getWidth(),d);if(rateSlot!=null)slots.add(new CardInfoDrawable.Slot(rateSlot,"ราคา / กม.",rate,false));}
   if(distanceOn&&!rateOn&&!pair){android.graphics.RectF r=freeInRow(occupied,rowY,88*d,38*d,card.getWidth(),d);if(r!=null)slots.add(new CardInfoDrawable.Slot(r,"ระยะทางงาน",km,false));}
   if(rateOn&&!distanceOn&&!pair){android.graphics.RectF r=freeInRow(occupied,rowY,94*d,38*d,card.getWidth(),d);if(r!=null)slots.add(new CardInfoDrawable.Slot(r,"ราคา / กม.",rate,false));}
   if(controls.getBoolean("cardShowNet",true)){android.graphics.RectF r=free(occupied,card.getWidth()-132*d,50*d,120*d,40*d,floor,d,true);if(r==null)r=free(occupied,card.getWidth()-116*d,50*d,104*d,36*d,floor,d,true);if(r==null)r=freeAcross(occupied,floor-36*d,110*d,36*d,card.getWidth(),d);if(r!=null)slots.add(new CardInfoDrawable.Slot(r,"รายได้สุทธิ",net,true));}
   String key=controls.getString("overlayStyleKey","")+token+":"+fee+":"+slots.toString()+controls.getString("rules","");if(key.equals(infoKeys.get(card)))continue;android.graphics.drawable.Drawable old=info.remove(card);if(old!=null)card.getOverlay().remove(old);infoKeys.remove(card);if(slots.isEmpty())continue;
   android.graphics.drawable.Drawable overlay=new CardInfoDrawable(d,slots,()->card.isShown()&&cards.containsKey(token)&&cards.get(token).get()==card,controls);overlay.setBounds(0,0,card.getWidth(),card.getHeight());card.getOverlay().add(overlay);info.put(card,overlay);infoKeys.put(card,key);infoLayoutKeys.put(card,layoutKey);
  }for(View card:new java.util.ArrayList<>(info.keySet()))if(!retained.contains(card)){card.getOverlay().remove(info.remove(card));infoKeys.remove(card);infoLayoutKeys.remove(card);}
 }
 private ViewTreeObserver observer;private final ViewTreeObserver.OnGlobalLayoutListener layout=this::changed;private final ViewTreeObserver.OnScrollChangedListener scroll=()->{if(touching||manualScroll){manualScroll=true;lastManualMotion=SystemClock.elapsedRealtime();}changed();};
 void dataChanged(){long at=SystemClock.elapsedRealtime();main.post(()->{eventAt=at;if(dataQueued)return;dataQueued=true;epoch++;main.postDelayed(()->{dataQueued=false;if(scheduled){eventPending=false;main.removeCallbacks(tick);main.post(tick);}},16);});}
 private void changed(){if(!scheduled||eventPending)return;eventPending=true;main.postDelayed(()->{eventPending=false;main.removeCallbacks(tick);tick.run();},Math.max(32,80-(SystemClock.elapsedRealtime()-lastRead)));}
 private void detach(){if(observer!=null&&observer.isAlive()){observer.removeOnGlobalLayoutListener(layout);observer.removeOnScrollChangedListener(scroll);}observer=null;}

