 private static final java.util.regex.Pattern PRICE_PATTERN=java.util.regex.Pattern.compile("[฿]\\s*([0-9][0-9,]*(?:[.]\\d{1,2})?)(?:\\s*[+]\\s*[฿]?\\s*([0-9][0-9,]*(?:[.]\\d{1,2})?))?");
 private static final java.util.regex.Pattern DISTANCE_PATTERN=java.util.regex.Pattern.compile("([0-9]+(?:[.]\\d+)?)\\s*กม[.]?");
 private void walk(View v,JSONArray rows,int[] visited,int[] texts)throws Exception{
  if(++visited[0]>3000||rows.length()>=60||!v.isShown())return;Rect rect=new Rect();if(!v.getGlobalVisibleRect(rect))return;
  JSONArray extra=services.get(v);if(extra!=null)for(int n=0;n<extra.length();n++)rows.put(node(v,rect,"service",extra.getString(n)));
  if(v instanceof ImageView){String id=name(v);String payment=null;
   if(id.equals("price_img")){
   Integer res=imageResources.get((ImageView)v);if(res==null)try{res=XposedHelpers.getIntField(v,"mResource");}catch(Throwable ignored){}
   String icon="";if(res!=null&&res!=0)try{icon=v.getResources().getResourceEntryName(res);}catch(Exception ignored){}
   if(icon.matches("ic_order_pay_type_cash_(20|24)px|payments_cash_outline_(thick|thin)"))payment="เงินสด";else if(icon.matches("ic_order_pay_type_credit_(20|24)px|payments_wallet_outline_(thick|thin)"))payment="เครดิต";
   if(payment!=null)rows.put(node(v,rect,"payment",payment));
  }}
  if(v instanceof TextView){CharSequence cs=((TextView)v).getText();if(cs!=null&&!cs.toString().isBlank()){texts[0]++;String text=cs.toString().trim();String value=null,kind=null;
   java.util.regex.Matcher price=PRICE_PATTERN.matcher(text);
   java.util.regex.Matcher distance=DISTANCE_PATTERN.matcher(text);
   if(price.find()){kind="price";value=price.group(1)+(price.group(2)==null?"":" + "+price.group(2));}
   else if(!text.contains("มากกว่า")&&com.fulllock.app.DetailViewParser.kilometres(text)!=null&&(text.contains("~")||text.contains("≈")||text.contains("จากคุณ"))){kind="pickupDistance";value=Double.toString(com.fulllock.app.DetailViewParser.kilometres(text)*1000);}
   else if(!text.contains("มากกว่า")&&distance.find()){kind=(text.contains("~")||text.contains("≈")||text.contains("จากคุณ"))?"pickupDistance":"distance";value=kind.equals("pickupDistance")?Double.toString(Double.parseDouble(distance.group(1))*1000):distance.group(1);}
   else if(text.matches("^(ขนส่งทันที|ส่งปกติ|ส่งด่วนพิเศษ|ส่งประหยัด|ส่งแบบประหยัด|มอเตอร์ไซค์|ขนส่งสินค้า|รับ-ส่งผู้โดยสาร)$")){kind="label";value=text;}
   if((text.equalsIgnoreCase("COD")||text.equals("เก็บเงินปลายทาง")||text.equals("เก็บเงินค่าสินค้า"))&&inBadge(v)){kind="service";value="เก็บเงินปลายทาง (COD)";}
   String resource="";try{resource=v.getResources().getResourceEntryName(v.getId());}catch(Exception ignored){}
   if((resource.equals("home_item_stop_first")||resource.equals("home_item_stop_last"))&&text.matches("[\\p{L}\\p{M}0-9 .()\\-]{1,80}")){kind=resource.equals("home_item_stop_first")?"origin":"destination";value=text;}

   if(text.contains("ขนส่งทันที"))rows.put(node(v,rect,"timing","ขนส่งทันที"));
   else if(text.matches("^(วันนี้|พรุ่งนี้|[0-9]{1,2}[/ ].*).*[0-9]{1,2}:[0-9]{2}.*"))rows.put(node(v,rect,"timing","งานล่วงหน้า"));
   String reduction=com.fulllock.app.Commission.reductionLabel(text);if(reduction!=null)rows.put(node(v,rect,"commissionReduction",reduction));
     if(value!=null)rows.put(node(v,rect,kind,value));
  }}
  if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount()&&visited[0]<3000&&rows.length()<60;n++)walk(g.getChildAt(n),rows,visited,texts);}
 }
