 private boolean inBadge(View v){for(int i=0;i<6&&v!=null;i++){if(v.getClass().getName().endsWith("BadgeFlexboxLayout"))return true;v=v.getParent() instanceof View?(View)v.getParent():null;}return false;}
 private String name(View v){try{return v.getResources().getResourceEntryName(v.getId());}catch(Exception e){return "";}}
 private JSONObject node(View v,Rect r,String kind,String value)throws Exception{
  String token="";int cardTop=-1;View candidate=v;int origin=originId,dest=destId,price=priceId;
  for(int i=0;i<10&&candidate!=null;i++){if(origin!=0&&dest!=0&&price!=0&&candidate.findViewById(origin)!=null&&candidate.findViewById(dest)!=null&&candidate.findViewById(price)!=null){int[] xy=new int[2];candidate.getLocationOnScreen(xy);cardTop=xy[1];token=tokens.get(candidate);if(token==null){token=fingerprint(candidate);tokens.put(candidate,token);}cards.put(token,new WeakReference<>(candidate));break;}candidate=candidate.getParent() instanceof View?(View)candidate.getParent():null;}
  return new JSONObject().put("kind",kind).put("value",value).put("viewId",name(v)).put("cardTop",cardTop).put("cardToken",token).put("cardKey",candidate!=null&&!token.isEmpty()?contentKey(candidate):"").put("left",r.left).put("top",r.top).put("right",r.right).put("bottom",r.bottom);
 }
 private View findClickTarget(View card){View start=card.findViewById(originId);View v=start==null?card:start.getParent() instanceof View?(View)start.getParent():card;for(int i=0;i<8&&v!=null;i++){if(v.getClass().getName().contains("RecyclerView"))return null;if(v instanceof ViewGroup&&v.isShown()&&v.isEnabled()&&v.isClickable()&&v.hasOnClickListeners())return v;if(v==card)break;v=v.getParent() instanceof View?(View)v.getParent():null;}v=card;for(int i=0;i<3&&v!=null;i++){if(v.getClass().getName().contains("RecyclerView"))return null;if(v.isShown()&&v.isEnabled()&&v.isClickable()&&v.hasOnClickListeners())return v;v=v.getParent() instanceof View?(View)v.getParent():null;}return null;}
 private static String hex12(byte[] digest){char[] out=new char[24];String digits="0123456789abcdef";for(int i=0;i<12;i++){int b=digest[i]&255;out[i*2]=digits.charAt(b>>>4);out[i*2+1]=digits.charAt(b&15);}return new String(out);}
 private String fingerprint(View card){return digest(card,true);}
 private String contentKey(View card){String key=contentKeys.get(card);if(key==null){key=semanticDigest(card);contentKeys.put(card,key);}return key;}
 private String semanticDigest(View card){try{StringBuilder text=new StringBuilder();appendSemantic(card,text,new int[]{0});byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));return hex12(bytes);}catch(Exception e){return "";}}
 private void appendSemantic(View v,StringBuilder s,int[] count){if(++count[0]>300)return;if(v instanceof TextView){CharSequence cs=((TextView)v).getText();if(cs!=null){String t=cs.toString().trim();if(t.contains("ขนส่งทันที"))s.append("|NOW");else if(!t.contains("กม.")&&!t.contains("km"))s.append('|').append(t);}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)appendSemantic(g.getChildAt(i),s,count);}}
 private String digest(View card,boolean identity){try{StringBuilder text=new StringBuilder(identity?String.valueOf(System.identityHashCode(card)):"");appendText(card,text,new int[]{0});byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));return hex12(digest);}catch(Exception e){return "";}}
 private void appendText(View v,StringBuilder s,int[] count){if(++count[0]>300)return;if(v instanceof TextView){CharSequence t=((TextView)v).getText();if(t!=null)s.append('|').append(t);}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)appendText(g.getChildAt(i),s,count);}}
 private final java.util.WeakHashMap<View,String> markGeometry=new java.util.WeakHashMap<>();
 private void applyMarks(java.util.List<String> matched){if(controls!=null&&!controls.getBoolean("drawCards",true))matched=java.util.Collections.emptyList();for(var e:new java.util.ArrayList<>(marks.entrySet())){String geometry=header(e.getKey()).toString()+e.getKey().getWidth()+controls.getString("rules","");if(!geometry.equals(markGeometry.get(e.getKey()))){e.getKey().getOverlay().remove(e.getValue());marks.remove(e.getKey());markGeometry.remove(e.getKey());}}for(var entry:new java.util.ArrayList<>(marks.entrySet())){if(!matched.contains(fingerprint(entry.getKey()))){entry.getKey().getOverlay().remove(entry.getValue());marks.remove(entry.getKey());}}for(String token:matched){View card=cards.containsKey(token)?cards.get(token).get():null;if(card==null||marks.containsKey(card))continue;android.graphics.drawable.Drawable mark=new MatchBadgeDrawable(c.getResources().getDisplayMetrics().density,()->card.isShown()&&cards.containsKey(token)&&cards.get(token).get()==card,header(card),controls);mark.setBounds(0,0,card.getWidth(),card.getHeight());card.getOverlay().add(mark);marks.put(card,mark);markGeometry.put(card,header(card).toString()+card.getWidth()+controls.getString("rules",""));}}

